	// Add triple
	triple := message.Triple{
		Subject:   "c360.platform.robotics.mav1.drone.001",
		Predicate: "robotics.battery.level",
		Object:    85.5,
		Timestamp: time.Now(),
	}

	data, err := json.Marshal(graph.AppendTriplesRequest{Triples: []message.Triple{triple}})
	require.NoError(t, err)
