// ====================================================================================
// Context Handling Tests
// ====================================================================================

func TestComponent_RespectsContext_Cancellation(t *testing.T) {
	t.Skip("requires real NATS connection - move to integration tests")
	comp := createTestComponentWithMockKV(t)
	ctx, cancel := context.WithCancel(context.Background())

	require.NoError(t, comp.Initialize())
	require.NoError(t, comp.Start(ctx))

	// Cancel context
	cancel()

	// Allow time for cancellation to propagate
	time.Sleep(100 * time.Millisecond)

	// Component should handle cancellation gracefully
	err := comp.Stop(context.Background())
	assert.NoError(t, err)
}

func TestComponent_RespectsContext_Timeout(t *testing.T) {
	comp := createTestComponentWithMockKV(t)
	ctx, cancel := context.WithDeadline(context.Background(), time.Unix(1, 0))
	defer cancel()

	require.NoError(t, comp.Initialize())

	// An already-expired caller deadline is rejected before lifecycle authority
	// or connection work is acquired.
	err := comp.Start(ctx)
	require.Error(t, err)
	assert.ErrorIs(t, err, context.DeadlineExceeded)
	assert.False(t, comp.lifecycleUsed)
}

